import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 1000010;
    static final long MOD_CONST = 1000000007;
    static long p_value, k_value, answer_value = 1;
    static int[] visited_array = new int[MAX_LIMIT];
    static int[] count_array = new int[MAX_LIMIT];

    static void run_dfs(int n, int length) {
        if (visited_array[n] == 1) {
            count_array[length]++;
            return;
        }
        visited_array[n] = 1;
        run_dfs((int)(((long)n * k_value) % p_value), length + 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p_value = sc.nextLong();
        k_value = sc.nextLong();

        if (k_value != 0 && k_value != 1) {
            for (int i = 1; i < p_value; i++) {
                if (visited_array[i] == 0) {
                    run_dfs(i, 0);
                }
            }
            for (int i = 1; i <= p_value; i++) {
                for (int j = 1; j <= count_array[i]; j++) {
                    answer_value = (answer_value * (count_array[i] * i + 1)) % MOD_CONST;
                }
            }
        } else if (k_value == 0) {
            for (int i = 1; i < p_value; i++) {
                answer_value = (answer_value * p_value) % MOD_CONST;
            }
        } else if (k_value == 1) {
            for (int i = 1; i <= p_value; i++) {
                answer_value = (answer_value * p_value) % MOD_CONST;
            }
        }
        System.out.println(answer_value);
        sc.close();
    }
}

